CREATE OR ALTER PROCEDURE [dbo].[uspCustomerComplaint_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @DeliveryOrderId UNIQUEIDENTIFIER = NULL
	, @DeliveryRouteId UNIQUEIDENTIFIER = NULL
	, @ComplaintStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ComplaintNo]
			, t.[CustomerId]
			, j1.[DisplayName] AS [CustomerName]
			, t.[OrderId]
			, j2.[OrderNo] AS [OrderName]
			, t.[DeliveryOrderId]
			, j3.[DeliveryNo] AS [DeliveryOrderName]
			, t.[DeliveryRouteId]
			, j4.[Name] AS [DeliveryRouteName]
			, t.[SourceChannel]
			, t.[CategoryCode]
			, t.[Severity]
			, t.[Description]
			, t.[ReceivedAt]
			, t.[SlaDueAt]
			, t.[ComplaintStatus]
			, t.[AssignedTo]
			, t.[ResolvedAt]
			, t.[Resolution]
			, t.[CreatedDate]
		FROM [dbo].[CustomerComplaint] AS t
		LEFT JOIN [dbo].[Customer] AS j1 ON j1.[Id] = t.[CustomerId]
		LEFT JOIN [dbo].[Order] AS j2 ON j2.[Id] = t.[OrderId]
		LEFT JOIN [dbo].[DeliveryOrder] AS j3 ON j3.[Id] = t.[DeliveryOrderId]
		LEFT JOIN [dbo].[DeliveryRoute] AS j4 ON j4.[Id] = t.[DeliveryRouteId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ComplaintNo] LIKE CONCAT('%', @SearchText, '%') OR t.[CategoryCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (@DeliveryOrderId IS NULL OR t.[DeliveryOrderId] = @DeliveryOrderId)
			AND (@DeliveryRouteId IS NULL OR t.[DeliveryRouteId] = @DeliveryRouteId)
			AND (ISNULL(@ComplaintStatus, '') = '' OR t.[ComplaintStatus] = @ComplaintStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'complaintNo' THEN r.[ComplaintNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'complaintNo' THEN r.[ComplaintNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerName' THEN r.[CustomerName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerName' THEN r.[CustomerName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderName' THEN r.[OrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderName' THEN r.[OrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderId' THEN r.[DeliveryOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryOrderName' THEN r.[DeliveryOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sourceChannel' THEN r.[SourceChannel] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'categoryCode' THEN r.[CategoryCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'categoryCode' THEN r.[CategoryCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'severity' THEN r.[Severity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'severity' THEN r.[Severity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'receivedAt' THEN r.[ReceivedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'receivedAt' THEN r.[ReceivedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'slaDueAt' THEN r.[SlaDueAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'slaDueAt' THEN r.[SlaDueAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'complaintStatus' THEN r.[ComplaintStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'complaintStatus' THEN r.[ComplaintStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'assignedTo' THEN r.[AssignedTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'assignedTo' THEN r.[AssignedTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'resolvedAt' THEN r.[ResolvedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'resolvedAt' THEN r.[ResolvedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'resolution' THEN r.[Resolution] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'resolution' THEN r.[Resolution] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
